<?php
header('Content-Type: application/json; charset=utf-8');
require_once __DIR__ . '/../Config/mikrotik.php';
require_once __DIR__ . '/../library/routeros_api.class.php';
try{$config=new MikroTikConfig();$router=$config->getRouter();if(!$router){echo json_encode(['status'=>'offline','message'=>'Router tidak tersedia']);exit;}$api=new RouterosAPI();$api->debug=false;if(!$api->connect($router['ip_address'],$router['username'],$router['password'],$router['api_port'])){echo json_encode(['status'=>'offline','message'=>'Router tidak dapat terhubung']);exit;}$items=$api->comm('/ip/route/print');$api->disconnect();$rows=[];foreach($items as $x){$rows[]=['id'=>$x['.id']??'','dst'=>$x['dst-address']??'-','gateway'=>$x['gateway']??'-','interface'=>$x['interface']??'-','distance'=>$x['distance']??'-','routing_mark'=>$x['routing-mark']??'main','active'=>isset($x['active']),'dynamic'=>isset($x['dynamic']),'disabled'=>isset($x['disabled']),'scope'=>$x['scope']??'-','target_scope'=>$x['target-scope']??'-'];}echo json_encode(['status'=>'online','router'=>$router['router_name'],'routes'=>$rows]);}catch(Throwable $e){http_response_code(500);echo json_encode(['status'=>'error','message'=>$e->getMessage()]);}